changeSet.sql:
-- Удаляем старую таблицу (если она существует)
DROP TABLE IF EXISTS `""index""`;

-- Создаём новую таблицу с правильным именем и структурой
CREATE TABLE `index` (
id BIGINT AUTO_INCREMENT PRIMARY KEY,
page_id BIGINT NOT NULL,
lemma_id BIGINT NOT NULL,
`rank` FLOAT NOT NULL,
CONSTRAINT fk_index_page FOREIGN KEY (page_id) REFERENCES page(id) ON DELETE CASCADE,
CONSTRAINT fk_index_lemma FOREIGN KEY (lemma_id) REFERENCES lemma(id) ON DELETE CASCADE,
UNIQUE KEY unique_page_lemma (page_id, lemma_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Создаём индексы
CREATE INDEX idx_page_id ON `index` (page_id);
CREATE INDEX idx_lemma_id ON `index` (lemma_id);
CREATE INDEX idx_rank ON `index` (`rank`);
